extends Node2D
## GridDraw — draws the séance board: dark checker + grid lines, 32px cells.
## Attached to the Board node; pure visual, reads nothing.

const CELL: float = 32.0
const W: int = 8
const H: int = 8
const COL_DARK := Color("1b2230")
const COL_LIGHT := Color("20293a")
const COL_GRID := Color("2a3547")

func _draw() -> void:
	for y in H:
		for x in W:
			var col: Color = COL_DARK if (x + y) % 2 == 0 else COL_LIGHT
			draw_rect(Rect2(x * CELL, y * CELL, CELL, CELL), col)
	for i in W + 1:
		draw_line(Vector2(i * CELL, 0), Vector2(i * CELL, H * CELL), COL_GRID, 1.0)
	for i in H + 1:
		draw_line(Vector2(0, i * CELL), Vector2(W * CELL, i * CELL), COL_GRID, 1.0)
